33	/// Base class for all errors.
34	class ErrorInfoBase : public RTTIExtends<ErrorInfoBase, RTTIRoot> {
35	public:
36	  virtual std::string toString() const noexcept = 0;
37	
38	private:
39	#if ORC_RT_ENABLE_EXCEPTIONS
40	  friend class Error;
41	  friend Error restore_error(ErrorInfoBase &&) noexcept;
42	
43	  virtual void throwAsException() = 0;
44	
45	  virtual Error restoreError() noexcept = 0;
46	#endif // ORC_RT_ENABLE_EXCEPTIONS
47	};
48	
49	/// Like RTTI-extends, but injects error-related helper methods.
50	template <typename ThisT, typename ParentT>
51	class ErrorExtends : public ParentT {
52	public:
53	  static_assert(std::is_base_of_v<ErrorInfoBase, ParentT>,
54	                "ErrorExtends must extend ErrorInfoBase derivatives");
55	
56	  // Inherit constructors and isA methods from ParentT.
57	  using ParentT::isA;
58	  using ParentT::ParentT;
59	
60	  static char ID;
61	
62	  static const void *classID() noexcept { return &ThisT::ID; }
63	
64	  const void *dynamicClassID() const noexcept override { return &ThisT::ID; }
65	
66	  bool isA(const void *const ClassID) const noexcept override {
67	    return ClassID == classID() || ParentT::isA(ClassID);
68	  }
69	
70	  static bool classof(const RTTIRoot *R) noexcept { return R->isA<ThisT>(); }
71	
72	#if ORC_RT_ENABLE_EXCEPTIONS
73	  void throwAsException() override {
74	    throw ThisT(std::move(static_cast<ThisT &>(*this)));
75	  }
76	
77	  Error restoreError() noexcept override;
78	#endif // ORC_RT_ENABLE_EXCEPTIONS
79	};
80	
81	template <typename ThisT, typename ParentT>
82	char ErrorExtends<ThisT, ParentT>::ID = 0;
83	
84	/// Represents an environmental error.
85	class [[nodiscard]] Error {
86	
87	  template <typename T> friend class Expected;
88	
89	  friend Error make_error(std::unique_ptr<ErrorInfoBase> Payload) noexcept;
90	
91	  template <typename... HandlerTs>
92	  friend Error handleErrors(Error E, HandlerTs &&...Hs);
93	
94	  friend orc_rt_ErrorRef wrap(Error Err) noexcept;
95	
96	public:
97	  /// Destroy this error. Aborts if error was not checked, or was checked but
98	  /// not handled.
99	  ~Error() noexcept { assertIsChecked(); }
100	
101	  Error(const Error &) = delete;
102	  Error &operator=(const Error &) = delete;
103	
104	  /// Move-construct an error. The newly constructed error is considered
105	  /// unchecked, even if the source error had been checked. The original error
106	  /// becomes a checked success value.
107	  Error(Error &&Other) noexcept {
108	    setChecked(true);
109	    *this = std::move(Other);
110	  }
111	
112	  /// Move-assign an error value. The current error must represent success, you
113	  /// you cannot overwrite an unhandled error. The current error is then
114	  /// considered unchecked. The source error becomes a checked success value,
115	  /// regardless of its original state.
116	  Error &operator=(Error &&Other) noexcept {
117	    // Don't allow overwriting of unchecked values.
118	    assertIsChecked();
119	    setPtr(Other.getPtr());
120	
121	    // This Error is unchecked, even if the source error was checked.
122	    setChecked(false);
123	
124	    // Null out Other's payload and set its checked bit.
125	    Other.setPtr(nullptr);
126	    Other.setChecked(true);
127	
128	    return *this;
129	  }
130	
131	  /// Create a success value.
132	  static Error success() noexcept { return Error(); }
133	
134	  /// Error values convert to true for failure values, false otherwise.
135	  explicit operator bool() noexcept {
136	    setChecked(getPtr() == nullptr);
137	    return getPtr() != nullptr;
138	  }
139	
140	  /// Return true if this Error contains a failure value of the given type.
141	  template <typename ErrT> bool isA() const noexcept {
142	    return getPtr() && getPtr()->isA<ErrT>();
143	  }
144	
145	#if ORC_RT_ENABLE_EXCEPTIONS
146	  void throwOnFailure() {
147	    if (auto P = takePayload())
148	      P->throwAsException();
149	  }
150	#endif // ORC_RT_ENABLE_EXCEPTIONS
151	
152	private:
153	  Error() noexcept = default;
154	
155	  Error(std::unique_ptr<ErrorInfoBase> ErrInfo) noexcept {
156	    auto RawErrPtr = reinterpret_cast<uintptr_t>(ErrInfo.release());
157	    assert((RawErrPtr & 0x1) == 0 && "ErrorInfo is insufficiently aligned");
158	    ErrPtr = RawErrPtr | 0x1;
159	  }
160	
161	  void assertIsChecked() noexcept {
162	    if (ORC_RT_UNLIKELY(!isChecked() || getPtr())) {
163	      fprintf(stderr, "Error must be checked prior to destruction.\n");
164	      abort(); // Some sort of JIT program abort?
165	    }
166	  }
167	
168	  template <typename ErrT = ErrorInfoBase> ErrT *getPtr() const noexcept {
169	    return reinterpret_cast<ErrT *>(ErrPtr & ~uintptr_t(1));
170	  }
171	
172	  void setPtr(ErrorInfoBase *Ptr) noexcept {
173	    ErrPtr = (reinterpret_cast<uintptr_t>(Ptr) & ~uintptr_t(1)) | (ErrPtr & 1);
174	  }
175	
176	  bool isChecked() const noexcept { return ErrPtr & 0x1; }
177	
178	  void setChecked(bool Checked) noexcept {
179	    ErrPtr = (ErrPtr & ~uintptr_t(1)) | Checked;
180	  }
181	
182	  template <typename ErrT = ErrorInfoBase>
183	  std::unique_ptr<ErrT> takePayload() noexcept {
184	    static_assert(std::is_base_of_v<ErrorInfoBase, ErrT>,
185	                  "ErrT is not an ErrorInfoBase subclass");
186	    std::unique_ptr<ErrT> Tmp(getPtr<ErrT>());
187	    setPtr(nullptr);
188	    setChecked(true);
189	    return Tmp;
190	  }
191	
192	  uintptr_t ErrPtr = 0;
193	};
194	
195	/// Create an Error from an ErrorInfoBase.
196	inline Error make_error(std::unique_ptr<ErrorInfoBase> Payload) noexcept {
197	  return Error(std::move(Payload));
198	}
199	
200	#if ORC_RT_ENABLE_EXCEPTIONS
201	
202	template <typename ThisT, typename ParentT>
203	Error ErrorExtends<ThisT, ParentT>::restoreError() noexcept {
204	  return make_error(
205	      std::make_unique<ThisT>(std::move(*static_cast<ThisT *>(this))));
206	}
207	
208	inline Error restore_error(ErrorInfoBase &&EIB) noexcept {
209	  return EIB.restoreError();
210	}
211	
212	#endif // ORC_RT_ENABLE_EXCEPTIONS
213	
214	/// Construct an error of ErrT with the given arguments.
215	template <typename ErrT, typename... ArgTs> Error make_error(ArgTs &&...Args) {
216	  static_assert(std::is_base_of<ErrorInfoBase, ErrT>::value,
217	                "ErrT is not an ErrorInfoBase subclass");
218	  return make_error(std::make_unique<ErrT>(std::forward<ArgTs>(Args)...));
219	}
220	
221	inline orc_rt_ErrorRef wrap(Error Err) noexcept {
222	  return reinterpret_cast<orc_rt_ErrorRef>(Err.takePayload().release());
223	}
224	
225	inline Error unwrap(orc_rt_ErrorRef ErrRef) noexcept {
226	  return make_error(std::unique_ptr<ErrorInfoBase>(
227	      reinterpret_cast<ErrorInfoBase *>(ErrRef)));
228	}
