232	template <typename RetT, typename ArgT> struct ErrorHandlerTraitsImpl;
233	
234	// Specialization for Error(ErrT&).
235	template <typename ErrT> struct ErrorHandlerTraitsImpl<Error, ErrT &> {
236	  static bool appliesTo(const ErrorInfoBase &E) noexcept {
237	    return E.template isA<ErrT>();
238	  }
239	  template <typename HandlerT>
240	  static Error apply(HandlerT &&H, std::unique_ptr<ErrorInfoBase> E) {
241	    assert(appliesTo(*E) && "Applying incorrect handler");
242	    return H(static_cast<ErrT &>(*E));
243	  }
244	};
245	
246	// Specialization for void(ErrT&).
247	template <typename ErrT> struct ErrorHandlerTraitsImpl<void, ErrT &> {
248	  static bool appliesTo(const ErrorInfoBase &E) noexcept {
249	    return E.template isA<ErrT>();
250	  }
251	  template <typename HandlerT>
252	  static Error apply(HandlerT &&H, std::unique_ptr<ErrorInfoBase> E) {
253	    assert(appliesTo(*E) && "Applying incorrect handler");
254	    H(static_cast<ErrT &>(*E));
255	    return Error::success();
256	  }
257	};
258	
259	// Specialization for Error(std::unique_ptr<ErrT>).
260	template <typename ErrT>
261	struct ErrorHandlerTraitsImpl<Error, std::unique_ptr<ErrT>> {
262	  static bool appliesTo(const ErrorInfoBase &E) noexcept {
263	    return E.template isA<ErrT>();
264	  }
265	  template <typename HandlerT>
266	  static Error apply(HandlerT &&H, std::unique_ptr<ErrorInfoBase> E) {
267	    assert(appliesTo(*E) && "Applying incorrect handler");
268	    std::unique_ptr<ErrT> SubE(static_cast<ErrT *>(E.release()));
269	    return H(std::move(SubE));
270	  }
271	};
272	
273	// Specialization for void(std::unique_ptr<ErrT>).
274	template <typename ErrT>
275	struct ErrorHandlerTraitsImpl<void, std::unique_ptr<ErrT>> {
276	  static bool appliesTo(const ErrorInfoBase &E) noexcept {
277	    return E.template isA<ErrT>();
278	  }
279	  template <typename HandlerT>
280	  static Error apply(HandlerT &&H, std::unique_ptr<ErrorInfoBase> E) {
281	    assert(appliesTo(*E) && "Applying incorrect handler");
282	    std::unique_ptr<ErrT> SubE(static_cast<ErrT *>(E.release()));
283	    H(std::move(SubE));
284	    return Error::success();
285	  }
286	};
287	
288	template <bool /* is_const */, bool /* is_noexcept */, typename RetT,
289	          typename ArgT>
290	struct ErrorHandlerTraitsImplAdapter : ErrorHandlerTraitsImpl<RetT, ArgT> {};
291	
292	} // namespace detail.
293	
294	template <typename C>
295	struct ErrorHandlerTraits
296	    : public CallableTraitsHelper<detail::ErrorHandlerTraitsImplAdapter, C> {};
297	
298	inline Error handleErrorsImpl(std::unique_ptr<ErrorInfoBase> Payload) {
299	  return make_error(std::move(Payload));
300	}
301	
302	template <typename HandlerT, typename... HandlerTs>
303	Error handleErrorsImpl(std::unique_ptr<ErrorInfoBase> Payload,
304	                       HandlerT &&Handler, HandlerTs &&...Handlers) {
305	  if (ErrorHandlerTraits<HandlerT>::appliesTo(*Payload))
306	    return ErrorHandlerTraits<HandlerT>::apply(std::forward<HandlerT>(Handler),
307	                                               std::move(Payload));
308	  return handleErrorsImpl(std::move(Payload),
309	                          std::forward<HandlerTs>(Handlers)...);
310	}
311	
312	/// Pass the ErrorInfo(s) contained in E to their respective handlers. Any
313	/// unhandled errors (or Errors returned by handlers) are re-concatenated and
314	/// returned.
315	/// Because this function returns an error, its result must also be checked
316	/// or returned. If you intend to handle all errors use handleAllErrors
317	/// (which returns void, and will abort() on unhandled errors) instead.
318	template <typename... HandlerTs>
319	Error handleErrors(Error E, HandlerTs &&...Hs) {
320	  if (!E)
321	    return Error::success();
322	  return handleErrorsImpl(E.takePayload(), std::forward<HandlerTs>(Hs)...);
323	}
324	
325	/// Behaves the same as handleErrors, except that by contract all errors
326	/// *must* be handled by the given handlers (i.e. there must be no remaining
327	/// errors after running the handlers, or llvm_unreachable is called).
328	template <typename... HandlerTs>
329	void handleAllErrors(Error E, HandlerTs &&...Handlers) {
330	  cantFail(handleErrors(std::move(E), std::forward<HandlerTs>(Handlers)...));
331	}
332	
333	/// Helper for Errors used as out-parameters.
334	/// Sets the 'checked' flag on construction, resets it on destruction.
335	class ErrorAsOutParameter {
336	public:
337	  ErrorAsOutParameter(Error *Err) noexcept : Err(Err) {
338	    // Raise the checked bit if Err is success.
339	    if (Err)
340	      (void)!!*Err;
341	  }
342	
343	  ErrorAsOutParameter(Error &Err) noexcept : Err(&Err) { (void)!!Err; }
344	
345	  ~ErrorAsOutParameter() noexcept {
346	    // Clear the checked bit.
347	    if (Err && !*Err)
348	      *Err = Error::success();
349	  }
350	
351	private:
352	  Error *Err;
353	};
354	
355	/// Tag to force construction of an Expected value in the success state. See
356	/// Expected constructor for details.
357	struct ForceExpectedSuccessValue {};
358	
359	template <typename T> class [[nodiscard]] Expected {
360	
361	  template <class OtherT> friend class Expected;
362	
363	  static constexpr bool IsRef = std::is_reference_v<T>;
364	  using wrap = std::reference_wrapper<std::remove_reference_t<T>>;
365	  using error_type = std::unique_ptr<ErrorInfoBase>;
366	  using storage_type = std::conditional_t<IsRef, wrap, T>;
367	  using value_type = T;
368	
369	  using reference = std::remove_reference_t<T> &;
370	  using const_reference = const std::remove_reference_t<T> &;
371	  using pointer = std::remove_reference_t<T> *;
372	  using const_pointer = const std::remove_reference_t<T> *;
373	
374	public:
375	  /// Create an Expected from a failure value.
376	  Expected(Error Err) noexcept : HasError(true), Unchecked(true) {
377	    assert(Err && "Cannot create Expected<T> from Error success value");
378	    new (getErrorStorage()) error_type(Err.takePayload());
379	  }
380	
381	  template <typename OtherT>
382	  Expected(OtherT &&Val, ForceExpectedSuccessValue _,
383	           std::enable_if_t<std::is_convertible_v<OtherT, T>> * = nullptr)
384	      : HasError(false), Unchecked(true) {
385	    new (getStorage()) storage_type(std::forward<OtherT>(Val));
386	  }
387	
388	  /// Create an Expected from a T value.
389	  template <typename OtherT>
390	  Expected(OtherT &&Val,
391	           std::enable_if_t<std::is_convertible_v<OtherT, T>> * = nullptr)
392	      : HasError(false), Unchecked(true) {
393	    new (getStorage()) storage_type(std::forward<OtherT>(Val));
394	  }
395	
396	  /// Move-construct an Expected<T> from an Expected<OtherT>.
397	  Expected(Expected &&Other) { moveConstruct(std::move(Other)); }
398	
399	  /// Move construct an Expected<T> value from an Expected<OtherT>, where OtherT
400	  /// must be convertible to T.
401	  template <class OtherT>
402	  Expected(Expected<OtherT> &&Other,
403	           std::enable_if_t<std::is_convertible_v<OtherT, T>> * = nullptr) {
404	    moveConstruct(std::move(Other));
405	  }
406	
407	  /// Move construct an Expected<T> value from an Expected<OtherT>, where OtherT
408	  /// isn't convertible to T.
409	  template <class OtherT>
410	  explicit Expected(
411	      Expected<OtherT> &&Other,
412	      std::enable_if_t<!std::is_convertible_v<OtherT, T>> * = nullptr) {
413	    moveConstruct(std::move(Other));
414	  }
415	
416	  /// Move-assign from another Expected<T>.
417	  Expected &operator=(Expected &&Other) {
418	    moveAssign(std::move(Other));
419	    return *this;
420	  }
421	
422	  /// Destroy an Expected<T>.
423	  ~Expected() {
424	    assertIsChecked();
425	    if (!HasError)
426	      getStorage()->~storage_type();
427	    else
428	      getErrorStorage()->~error_type();
429	  }
430	
431	  /// Returns true if this Expected value is in a success state (holding a T),
432	  /// and false if this Expected value is in a failure state.
433	  explicit operator bool() noexcept {
434	    Unchecked = HasError;
435	    return !HasError;
436	  }
437	
438	  /// Returns true if this Expected value holds an Error of type error_type.
439	  template <typename ErrT> bool isFailureOfType() const noexcept {
440	    return HasError && (*getErrorStorage())->template isA<ErrT>();
441	  }
442	
443	  /// Take ownership of the stored error.
444	  ///
445	  /// If this Expected value is in a success state (holding a T) then this
446	  /// method is a no-op and returns Error::success.
447	  ///
448	  /// If thsi Expected value is in a failure state (holding an Error) then this
449	  /// method returns the contained error and leaves this Expected in an
450	  /// 'empty' state from which it may be safely destructed but not otherwise
451	  /// accessed.
452	  Error takeError() noexcept {
453	    Unchecked = false;
454	    return HasError ? Error(std::move(*getErrorStorage())) : Error::success();
455	  }
456	
457	  /// Returns a pointer to the stored T value.
458	  pointer operator->() noexcept {
459	    assertIsChecked();
460	    return toPointer(getStorage());
461	  }
462	
463	  /// Returns a pointer to the stored T value.
464	  const_pointer operator->() const noexcept {
465	    assertIsChecked();
466	    return toPointer(getStorage());
467	  }
468	
469	  /// Returns a reference to the stored T value.
470	  reference operator*() noexcept {
471	    assertIsChecked();
472	    return *getStorage();
473	  }
474	
475	  /// Returns a reference to the stored T value.
476	  const_reference operator*() const noexcept {
477	    assertIsChecked();
478	    return *getStorage();
479	  }
480	
481	private:
482	  template <class T1>
483	  static bool compareThisIfSameType(const T1 &a, const T1 &b) noexcept {
484	    return &a == &b;
485	  }
486	
487	  template <class T1, class T2>
488	  static bool compareThisIfSameType(const T1 &a, const T2 &b) noexcept {
489	    return false;
490	  }
491	
492	  template <class OtherT> void moveConstruct(Expected<OtherT> &&Other) {
493	    HasError = Other.HasError;
494	    Unchecked = true;
495	    Other.Unchecked = false;
496	
497	    if (!HasError)
498	      new (getStorage()) storage_type(std::move(*Other.getStorage()));
499	    else
500	      new (getErrorStorage()) error_type(std::move(*Other.getErrorStorage()));
501	  }
502	
503	  template <class OtherT> void moveAssign(Expected<OtherT> &&Other) {
504	    assertIsChecked();
505	
506	    if (compareThisIfSameType(*this, Other))
507	      return;
508	
509	    this->~Expected();
510	    new (this) Expected(std::move(Other));
511	  }
512	
513	  pointer toPointer(pointer Val) noexcept { return Val; }
514	
515	  const_pointer toPointer(const_pointer Val) const noexcept { return Val; }
516	
517	  pointer toPointer(wrap *Val) noexcept { return &Val->get(); }
518	
519	  const_pointer toPointer(const wrap *Val) const noexcept {
520	    return &Val->get();
521	  }
522	
523	  storage_type *getStorage() noexcept {
524	    assert(!HasError && "Cannot get value when an error exists!");
525	    return reinterpret_cast<storage_type *>(&TStorage);
526	  }
527	
528	  const storage_type *getStorage() const noexcept {
529	    assert(!HasError && "Cannot get value when an error exists!");
530	    return reinterpret_cast<const storage_type *>(&TStorage);
531	  }
532	
533	  error_type *getErrorStorage() noexcept {
534	    assert(HasError && "Cannot get error when a value exists!");
535	    return reinterpret_cast<error_type *>(&ErrorStorage);
536	  }
537	
538	  const error_type *getErrorStorage() const noexcept {
539	    assert(HasError && "Cannot get error when a value exists!");
540	    return reinterpret_cast<const error_type *>(&ErrorStorage);
541	  }
542	
543	  void assertIsChecked() noexcept {
544	    if (ORC_RT_UNLIKELY(Unchecked)) {
545	      fprintf(stderr,
546	              "Expected<T> must be checked before access or destruction.\n");
547	      abort();
548	    }
549	  }
550	
551	  union {
552	    alignas(storage_type) char TStorage[sizeof(storage_type)];
553	    alignas(error_type) char ErrorStorage[sizeof(error_type)];
554	  };
555	
556	  bool HasError : 1;
557	  bool Unchecked : 1;
558	};
559	
560	/// Consume an error without doing anything.
561	inline void consumeError(Error Err) {
562	  handleAllErrors(std::move(Err), [](const ErrorInfoBase &) {});
563	}
564	
565	/// Consumes success values. It is a programmatic error to call this function
566	/// on a failure value.
567	inline void cantFail(Error Err) noexcept {
568	#ifndef NDEBUG
569	  // TODO: Log unhandled error.
570	  if (Err)
571	    abort();
572	#else
573	  Err.operator bool(); // Reset checked flag.
574	#endif
575	}
576	
577	/// Auto-unwrap an Expected<T> value in the success state. It is a programmatic
578	/// error to call this function on a failure value.
579	template <typename T> T cantFail(Expected<T> E) {
580	  assert(E && "cantFail called on failure value");
581	  consumeError(E.takeError());
582	  return std::move(*E);
583	}
584	
585	/// Auto-unwrap an Expected<T> value in the success state. It is a programmatic
586	/// error to call this function on a failure value.
587	template <typename T> T &cantFail(Expected<T &> E) {
588	  assert(E && "cantFail called on failure value");
589	  consumeError(E.takeError());
590	  return *E;
591	}
592	
593	/// Convert the given error to a string. The error value is consumed in the
594	/// process.
595	inline std::string toString(Error Err) noexcept {
596	  assert(Err && "Cannot convert success value to string");
597	  std::string ErrMsg;
598	  handleAllErrors(std::move(Err),
599	                  [&](const ErrorInfoBase &EIB) { ErrMsg = EIB.toString(); });
600	  return ErrMsg;
601	}
602	
603	/// Simple string error type.
604	class StringError : public ErrorExtends<StringError, ErrorInfoBase> {
605	public:
606	  StringError(std::string ErrMsg) noexcept : ErrMsg(std::move(ErrMsg)) {}
607	  std::string toString() const noexcept override { return ErrMsg; }
608	
609	private:
610	  std::string ErrMsg;
611	};
