613	/// APIs for C++ exception interop.
614	#if ORC_RT_ENABLE_EXCEPTIONS
615	
616	class ExceptionError : public ErrorExtends<ExceptionError, ErrorInfoBase> {
617	public:
618	  ExceptionError(std::exception_ptr E) noexcept : E(std::move(E)) {}
619	  std::string toString() const noexcept override;
620	  void throwAsException() override { std::rethrow_exception(E); }
621	
622	private:
623	  mutable std::exception_ptr E;
624	};
