626	namespace detail {
627	
628	// In general we need to wrap a return type of T with an Expected.
629	template <typename RetT> struct ErrorWrapImpl {
630	  typedef Expected<RetT> return_type;
631	
632	  template <typename OpFn> static return_type run(OpFn &&Op) { return Op(); }
633	};
634	
635	// If the return is already an Expected value then we don't need to add
636	// an additional level of wrapping.
637	template <typename RetT> struct ErrorWrapImpl<Expected<RetT>> {
638	  typedef Expected<RetT> return_type;
639	
640	  template <typename OpFn> static return_type run(OpFn &&Op) { return Op(); }
641	};
642	
643	// Errors stay errors.
644	template <> struct ErrorWrapImpl<Error> {
645	  typedef Error return_type;
646	
647	  template <typename OpFn> static return_type run(OpFn &&Op) { return Op(); }
648	};
649	
650	// void returns become Error returns.
651	template <> struct ErrorWrapImpl<void> {
652	  typedef Error return_type;
653	
654	  template <typename OpFn> static return_type run(OpFn &&Op) {
655	    Op();
656	    return Error::success();
657	  }
658	};
659	
660	template <bool /* is_const */, bool /* is_noexcept */, typename RetT>
661	struct ErrorWrapImplAdapter : ErrorWrapImpl<RetT> {};
662	
663	template <typename Callable>
664	struct ErrorWrap
665	    : public CallableTraitsHelper<detail::ErrorWrapImplAdapter, Callable> {};
666	
667	} // namespace detail
668	
669	/// Run the given callback capturing any exceptions thrown into an
670	/// Error / Expected failure value.
671	///
672	/// The return type depends on the return type of the callback:
673	///   - void callbacks return Error
674	///   - Error callbacks return Error
675	///   - Expected<T> callbacks return Expected<T>
676	///   - other T callbacks return Expected<T>
677	///
678	/// If the operation succeeds then...
679	///   - If its result is non-void it is returned as an Expected<T> success
680	///     value
681	///   - If its result is void then Error::success() is retured
682	///
683	/// If the operation fails then...
684	///   - If the exception type is std::unique_ptr<ErrorInfoBase> (i.e. a throw
685	///     orc_rt failure value) then an Error is constructed to hold the
686	///     failure value.
687	///   - If the exception has any other type then it's captured as an
688	///     ExceptionError.
689	///
690	/// The scheme allaws...
691	///   1. orc_rt::Error values that have been converted to exceptions via
692	///      Error::throwOnFailure to be converted back into Errors without loss
693	///      of dynamic type info.
694	///   2. Other Exceptions caught by this function to be converted back into
695	///      exceptions via Error::throwOnFailure without loss of dynamic
696	///      type info.
697	
698	template <typename OpFn>
699	typename detail::ErrorWrap<OpFn>::return_type
700	runCapturingExceptions(OpFn &&Op) noexcept {
701	  try {
702	    return detail::ErrorWrap<OpFn>::run(std::forward<OpFn>(Op));
703	  } catch (ErrorInfoBase &EIB) {
704	    return restore_error(std::move(EIB));
705	  } catch (...) {
706	    return make_error<ExceptionError>(std::current_exception());
707	  }
708	}
709	
710	#endif // ORC_RT_ENABLE_EXCEPTIONS
711	
712	} // namespace orc_rt
713	
714	#endif // ORC_RT_ERROR_H
715

