399	  Expected<int> A = make_error<CustomError>(42);
400	  EXPECT_DEATH(*A, "Expected<T> must be checked before access or destruction.")
401	      << "Incorrect Expected error value";
402	  consumeError(A.takeError());
403	}
404	
405	// Check that an Expected instance with an error triggers an abort if
406	// unhandled.
407	// Test runs in debug mode only.
408	TEST(ErrorDeathTest, UnhandledExpectedInFailureMode) {
409	  EXPECT_DEATH(
410	      { Expected<int> A = make_error<CustomError>(42); },
411	      "Expected<T> must be checked before access or destruction.")
412	      << "Unchecked Expected<T> failure value did not cause an abort()";
413	}
414	
415	// Test covariance of Expected.
416	TEST(ErrorTest, ExpectedCovariance) {
417	  class B {};
418	  class D : public B {};
419	
420	  Expected<B *> A1(Expected<D *>(nullptr));
421	  // Check A1 by converting to bool before assigning to it.
422	  (void)!!A1;
423	  A1 = Expected<D *>(nullptr);
424	  // Check A1 again before destruction.
425	  (void)!!A1;
426	
427	  Expected<std::unique_ptr<B>> A2(Expected<std::unique_ptr<D>>(nullptr));
428	  // Check A2 by converting to bool before assigning to it.
429	  (void)!!A2;
430	  A2 = Expected<std::unique_ptr<D>>(nullptr);
431	  // Check A2 again before destruction.
432	  (void)!!A2;
433	}
434	
435	// Test that Expected<Error> works as expected.
