458	// Test that Expected<Expected<T>> works as expected.
459	TEST(ErrorTest, ExpectedExpected) {
460	  {
461	    // Test success-success case.
462	    Expected<Expected<int>> E(Expected<int>(42), ForceExpectedSuccessValue());
463	    EXPECT_TRUE(!!E);
464	    cantFail(E.takeError());
465	    auto EI = std::move(*E);
