472	    // Test "failure" success case.
473	    Expected<Expected<int>> E(Expected<int>(make_error<StringError>("foo")),
474	                              ForceExpectedSuccessValue());
475	    EXPECT_TRUE(!!E);
476	    cantFail(E.takeError());
477	    auto EI = std::move(*E);
478	    EXPECT_FALSE(!!EI);
479	    EXPECT_EQ(toString(EI.takeError()), "foo");
